3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create request whose telephone is already used by an existing owner. Runs
11	 * after {@link RequireOwnerFields} has normalized the telephone to E.164 form, so the
12	 * comparison is between E.164 values. A conflict is reported as a 409 by
13	 * {@link org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneExceptionHandler}.
14	 */
15	public class RequireUniqueTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = Telephones.toE164(request.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone != null && telephone.equals(Telephones.toE164(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(telephone);
23	            }
24	        }
25	    }
26	}
