1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create request whose last name and address are already shared by an existing
11	 * owner, comparing case-insensitively with runs of whitespace collapsed to a single space.
12	 * The request may opt out of this rule by setting {@code sharesHousehold} true (e.g. a
13	 * spouse or family member living at the same address). A conflict is reported as a 409 by
14	 * {@link org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdExceptionHandler}.
15	 */
16	public class RequireUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = AddressNormalizer.normalize(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (lastName.equals(normalize(existing.getLastName()))
27	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
28	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
29	            }
30	        }
31	    }
32	
33	    /** Lower-case, trim, and collapse runs of whitespace to a single space. */
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
39	    }
