3	/**
4	 * Normalizes telephone numbers to E.164 form.
5	 *
6	 * <p>Spaces, dashes and brackets are stripped. When a leading {@code '+'} (an explicit
7	 * country code) is present it is kept as-is; otherwise country code {@code '+61'} is
8	 * assumed and a single leading {@code '0'} is dropped from the national digits. The
9	 * result must be {@code '+'} followed by 8 to 15 digits, else it cannot form a valid
10	 * E.164 number.
11	 *
12	 * <p>E.g. {@code "0412 345 678"} -> {@code "+61412345678"} and
13	 * {@code "+64 21 123 456"} -> {@code "+6421123456"}.
14	 */
15	public final class Telephones {
16	
17	    private Telephones() {
18	    }
19	
20	    /**
21	     * Converts a telephone number to its E.164 form, or returns {@code null} when the
22	     * input cannot form a valid E.164 number.
23	     */
24	    public static String toE164(String telephone) {
25	        if (telephone == null) {
26	            return null;
27	        }
28	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
29	        String digits;
30	        if (cleaned.startsWith("+")) {
31	            digits = cleaned.substring(1);
32	        }
33	        else {
34	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
35	            digits = "61" + national;
36	        }
37	        return digits.matches("\\d{8,15}") ? "+" + digits : null;
38	    }
39	}
