6	/**
7	 * Business-day rules for owner registration dates.
8	 *
9	 * <p>A registration date must fall on a business day. When the effective date (whether
10	 * supplied in the request or defaulted to the server date) lands on a Saturday or Sunday,
11	 * it is rolled forward to the next Monday.
12	 */
13	public final class BusinessDays {
14	
15	    private BusinessDays() {
16	    }
17	
18	    /**
19	     * Roll a date forward to a business day: a Saturday or Sunday becomes the next Monday;
20	     * any other day is returned unchanged.
21	     */
22	    public static LocalDate toBusinessDay(LocalDate date) {
23	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
24	            return date.plusDays(2);
25	        }
26	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
27	            return date.plusDays(1);
28	        }
29	        return date;
30	    }
31	}
