package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;

class BulkWarningScratchTest extends AcceptanceBase {

	@Test
	void warningTrueOnceMoreThan80CreatedToday() throws Exception {
		createMany(81); // 81 owners already created today
		int id = createOwnerOk(ownerNode()); // 82nd: 81 > 80 -> warning
		getOwner(id).andExpect(jsonPath("$.bulkSignupWarning").value(true));
	}

	@Test
	void warningFalseAtExactly80CreatedToday() throws Exception {
		createMany(80); // 80 owners already created today
		int id = createOwnerOk(ownerNode()); // 81st: 80 is NOT > 80 -> no warning
		getOwner(id).andExpect(jsonPath("$.bulkSignupWarning").value(false));
	}
}

